<template>
  <div class="security-page">
    <header class="page-heading"><div><h1>约束管理</h1><p>通过模板和表单生成可执行约束，不需要手写表达式或JSON</p></div><div><el-button :icon="Refresh" @click="load">刷新</el-button><el-button v-if="canCreate" type="primary" :icon="Plus" @click="open()">新建约束规则</el-button></div></header>
    <el-card shadow="never"><div class="toolbar"><el-input v-model="query.keyword" clearable placeholder="搜索名称或说明" @keyup.enter="load"/><el-select v-model="query.isEnabled" clearable placeholder="启用状态"><el-option label="启用" :value="true"/><el-option label="停用" :value="false"/></el-select><el-button type="primary" @click="load">查询</el-button></div>
      <el-table :data="items" v-loading="loading" border stripe size="small"><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="ruleName" label="约束名称" min-width="170"/><el-table-column prop="expression" label="违规表达式" min-width="220" show-overflow-tooltip/><el-table-column label="变量" width="70"><template #default="{row}">{{ Object.keys(row.bindings || {}).length }}</template></el-table-column><el-table-column label="动作" width="70"><template #default="{row}">{{ (row.violationActions || []).length }}</template></el-table-column><el-table-column prop="description" label="说明" min-width="160" show-overflow-tooltip/><el-table-column label="状态" width="85"><template #default="{row}"><el-switch v-model="row.isEnabled" :disabled="!canEdit" size="small" @change="value => setEnabled(row,value)"/></template></el-table-column><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button v-if="canEdit" link type="primary" @click="open(row)">编辑</el-button><el-popconfirm v-if="canDelete" title="确认删除该规则？" @confirm="remove(row)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="query.pageNo" v-model:page-size="query.pageSize" :total="total" layout="total,sizes,prev,pager,next" @current-change="load" @size-change="load"/></div>
    </el-card>
    <el-dialog v-model="visible" :title="mode === 'create' ? '新建约束规则' : '编辑约束规则'" width="980px" destroy-on-close>
      <el-form ref="formRef" :model="form" :rules="rules" label-width="92px"><el-row :gutter="16"><el-col :span="17"><el-form-item label="规则名称" prop="ruleName"><el-input v-model="form.ruleName"/></el-form-item></el-col><el-col :span="7"><el-form-item label="启用"><el-switch v-model="form.isEnabled"/></el-form-item></el-col></el-row><el-form-item label="规则说明"><el-input v-model="form.description" type="textarea" :rows="2"/></el-form-item>
        <section class="block"><div class="block-title"><strong>1.违规表达式</strong><span>选择模板，表达式由系统生成</span></div><el-row :gutter="12"><el-col :span="7"><el-form-item label="模板"><el-select v-model="form.template"><el-option label="变量比较" value="COMPARE"/><el-option label="布尔变量" value="BOOLEAN"/><el-option label="数值区间" value="RANGE"/><el-option v-if="form.existingExpression" label="保留历史表达式" value="EXISTING"/></el-select></el-form-item></el-col><template v-if="form.template === 'COMPARE'"><el-col :span="5"><el-form-item label="左变量"><el-select v-model="form.left"><el-option v-for="name in names" :key="name" :label="name" :value="name"/></el-select></el-form-item></el-col><el-col :span="4"><el-form-item label="比较符"><el-select v-model="form.operator"><el-option v-for="op in operators" :key="op" :label="op" :value="op"/></el-select></el-form-item></el-col><el-col :span="5"><el-form-item label="右变量"><el-select v-model="form.right"><el-option v-for="name in names" :key="name" :label="name" :value="name"/></el-select></el-form-item></el-col></template><template v-if="form.template === 'BOOLEAN'"><el-col :span="7"><el-form-item label="变量"><el-select v-model="form.left"><el-option v-for="name in names" :key="name" :label="name" :value="name"/></el-select></el-form-item></el-col><el-col :span="5"><el-form-item label="期望值"><el-select v-model="form.expected"><el-option label="true" :value="true"/><el-option label="false" :value="false"/></el-select></el-form-item></el-col></template><template v-if="form.template === 'RANGE'"><el-col :span="5"><el-form-item label="观测变量"><el-select v-model="form.left"><el-option v-for="name in names" :key="name" :label="name" :value="name"/></el-select></el-form-item></el-col><el-col :span="5"><el-form-item label="最小变量"><el-select v-model="form.min"><el-option v-for="name in names" :key="name" :label="name" :value="name"/></el-select></el-form-item></el-col><el-col :span="5"><el-form-item label="最大变量"><el-select v-model="form.max"><el-option v-for="name in names" :key="name" :label="name" :value="name"/></el-select></el-form-item></el-col></template></el-row><div class="preview">生成结果：<code>{{ expression }}</code></div></section>
        <section class="block"><div class="block-title"><strong>2.变量绑定</strong><span>选择变量来源而不是填写bindings JSON</span><el-button type="primary" plain size="small" @click="addBinding">添加变量</el-button></div><div v-for="(item,index) in form.bindings" :key="item.key" class="entry"><div class="entry-head">变量{{ index + 1 }}<el-button link type="danger" @click="form.bindings.splice(index,1)">删除</el-button></div><el-row :gutter="12"><el-col :span="6"><el-form-item label="变量名"><el-input v-model="item.name"/></el-form-item></el-col><el-col :span="7"><el-form-item label="绑定类型"><el-radio-group v-model="item.type"><el-radio value="OBSERVABLE">观测数据</el-radio><el-radio value="LITERAL">固定值</el-radio></el-radio-group></el-form-item></el-col><template v-if="item.type === 'LITERAL'"><el-col :span="5"><el-form-item label="数据类型"><el-select v-model="item.dataType"><el-option label="DOUBLE" value="DOUBLE"/><el-option label="INTEGER" value="INTEGER"/><el-option label="STRING" value="STRING"/><el-option label="BOOLEAN" value="BOOLEAN"/></el-select></el-form-item></el-col><el-col :span="6"><el-form-item label="固定值"><el-select v-if="item.dataType === 'BOOLEAN'" v-model="item.value"><el-option label="true" :value="true"/><el-option label="false" :value="false"/></el-select><el-input-number v-else-if="numeric(item.dataType)" v-model="item.value" :controls="false"/><el-input v-else v-model="item.value"/></el-form-item></el-col></template></el-row><template v-if="item.type === 'OBSERVABLE'"><el-row :gutter="12"><el-col :span="7"><el-form-item label="观测来源"><el-select v-model="item.sourceType"><el-option v-for="type in sourceTypes" :key="type" :label="sourceLabel(type)" :value="type"/></el-select></el-form-item></el-col><el-col :span="5"><el-form-item label="数据类型"><el-select v-model="item.dataType"><el-option v-for="type in dataTypes" :key="type" :label="type" :value="type"/></el-select></el-form-item></el-col></el-row><el-row v-if="deviceSource(item.sourceType)" :gutter="12"><el-col :span="7"><el-form-item label="设备模型"><el-select v-model="item.deviceModelId" @change="item.deviceInstanceId=null"><el-option v-for="model in models" :key="model.id" :label="model.modelName" :value="model.id"/></el-select></el-form-item></el-col><el-col :span="7"><el-form-item label="设备实例"><el-select v-model="item.deviceInstanceId" clearable placeholder="不选表示全部实例"><el-option v-for="device in instancesFor(item.deviceModelId)" :key="device.id" :label="device.instanceName || device.id" :value="device.id"/></el-select></el-form-item></el-col><el-col v-if="item.sourceType === 'DEVICE_ATTRIBUTE'" :span="7"><el-form-item label="设备属性"><el-select v-model="item.targetName" filterable allow-create><el-option v-for="attr in attributesFor(item.deviceModelId)" :key="attr.attributeName" :label="attr.attributeName" :value="attr.attributeName"/></el-select></el-form-item></el-col><el-col v-if="item.sourceType === 'DEVICE_OPERATION_STATE'" :span="5"><el-form-item label="状态空间"><el-select v-model="item.regionName"><el-option label="CMD" value="CMD"/><el-option label="OP" value="OP"/></el-select></el-form-item></el-col></el-row><el-row v-if="nodeSource(item.sourceType)" :gutter="12"><el-col :span="7"><el-form-item label="工作流"><el-select v-model="item.workflowTemplateId"><el-option v-for="flow in workflows" :key="flow.id" :label="flow.flowName" :value="flow.id"/></el-select></el-form-item></el-col><el-col :span="7"><el-form-item label="节点名称"><el-select v-model="item.nodeName" filterable allow-create><el-option v-for="node in nodesFor(item.workflowTemplateId)" :key="node.name" :label="node.name" :value="node.name"/></el-select></el-form-item></el-col><el-col v-if="item.sourceType === 'NODE_INTERNAL_VARIABLE'" :span="7"><el-form-item label="内部变量"><el-input v-model="item.variableName"/></el-form-item></el-col></el-row><el-row v-if="item.sourceType === 'TASK_LIFECYCLE_STATE'"><el-col :span="10"><el-form-item label="任务"><el-select v-model="item.taskId"><el-option v-for="task in tasks" :key="task.id" :label="(task.taskName || task.name || '任务') + '#' + task.id" :value="task.id"/></el-select></el-form-item></el-col></el-row></template></div></section>
        <section class="block"><div class="block-title"><strong>3.违规动作</strong><span>系统动作或设备能力都通过受约束表单配置</span><el-button type="primary" plain size="small" @click="addAction">添加动作</el-button></div><div v-for="(item,index) in form.actions" :key="item.key" class="entry"><div class="entry-head">动作{{ index + 1 }}<el-button link type="danger" @click="form.actions.splice(index,1)">删除</el-button></div><el-row :gutter="12"><el-col :span="8"><el-form-item label="动作类型"><el-radio-group v-model="item.type"><el-radio value="SYSTEM">系统处置</el-radio><el-radio value="DEVICE_CAPABILITY">设备能力</el-radio></el-radio-group></el-form-item></el-col></el-row><el-row v-if="item.type === 'SYSTEM'" :gutter="12"><el-col :span="7"><el-form-item label="系统动作"><el-select v-model="item.action"><el-option v-for="action in systemActions" :key="action" :label="action" :value="action"/></el-select></el-form-item></el-col><el-col v-if="item.action !== 'ALERT'" :span="9"><el-form-item label="目标任务"><el-select v-model="item.taskId"><el-option v-for="task in tasks" :key="task.id" :label="(task.taskName || task.name || '任务') + '#' + task.id" :value="task.id"/></el-select></el-form-item></el-col></el-row><el-row v-else :gutter="12"><el-col :span="9"><el-form-item label="目标设备"><el-select v-model="item.deviceInstanceId" @change="item.capabilityName=''"><el-option v-for="device in instances" :key="device.id" :label="device.instanceName || device.id" :value="device.id"/></el-select></el-form-item></el-col><el-col :span="9"><el-form-item label="设备能力"><el-select v-model="item.capabilityName" @change="initParameters(item)"><el-option v-for="capability in capabilitiesFor(item.deviceInstanceId)" :key="capability.capabilityName" :label="capability.capabilityName" :value="capability.capabilityName"/></el-select></el-form-item></el-col></el-row><el-row v-if="parameterDefinitions(item).length" :gutter="12"><el-col v-for="parameter in parameterDefinitions(item)" :key="parameter.name" :span="8"><el-form-item :label="parameter.name"><el-select v-if="parameter.dataType === &apos;BOOLEAN&apos;" v-model="item.parameters[parameter.name]"><el-option label="true" :value="true"/><el-option label="false" :value="false"/></el-select><el-input-number v-else-if="numeric(parameter.dataType)" v-model="item.parameters[parameter.name]" :controls="false"/><el-input v-else v-model="item.parameters[parameter.name]"/></el-form-item></el-col></el-row></div></section>
        <el-form-item label="持续阈值"><el-input-number v-model="form.windowSeconds" :controls="false" placeholder="不填写表示瞬时触发"/><span class="hint">秒，不填写表示瞬时触发</span></el-form-item>
      </el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template>
    </el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import axios from 'axios'
import { ElMessage,type FormInstance,type FormRules } from 'element-plus'
import { Plus,Refresh } from '@element-plus/icons-vue'
import { useAuthStore } from '../../stores/authStore'
const auth=useAuthStore(),canCreate=computed(()=>auth.hasPermission('constraint_rule:create')),canEdit=computed(()=>auth.hasPermission('constraint_rule:edit')),canDelete=computed(()=>auth.hasPermission('constraint_rule:delete'))
const loading=ref(false),saving=ref(false),visible=ref(false),mode=ref<'create'|'edit'>('create'),items=ref<any[]>([]),total=ref(0),formRef=ref<FormInstance>(),models=ref<any[]>([]),instances=ref<any[]>([]),workflows=ref<any[]>([]),tasks=ref<any[]>([])
const sourceTypes=ref(['DEVICE_ATTRIBUTE','DEVICE_OPERATION_STATE','DEVICE_COMMAND_LIFECYCLE','NODE_LIFECYCLE_STATE','NODE_INTERNAL_VARIABLE','TASK_LIFECYCLE_STATE']),dataTypes=ref(['INTEGER','DOUBLE','STRING','BOOLEAN']),systemActions=ref(['ABORT','PAUSE','ALERT']),query=reactive({pageNo:1,pageSize:20,keyword:'',isEnabled:undefined as boolean|undefined}),rules:FormRules={ruleName:[{required:true,message:'请输入约束名称',trigger:'blur'}]},operators=['>','>=','<','<=','==','!='];let serial=0
const binding=(name='observedValue')=>({key:++serial,name,type:'OBSERVABLE',sourceType:'DEVICE_ATTRIBUTE',dataType:'DOUBLE',deviceModelId:null,deviceInstanceId:null,targetName:'',regionName:'CMD',workflowTemplateId:null,nodeName:'',variableName:'',taskId:null,value:0})
const action=()=>({key:++serial,type:'SYSTEM',action:'ALERT',taskId:null,deviceInstanceId:null,capabilityName:'',parameters:{}})
const empty=()=>({id:null as number|null,ruleName:'',description:'',isEnabled:true,template:'COMPARE',existingExpression:'',left:'observedValue',right:'threshold',operator:'>',expected:true,min:'minimum',max:'maximum',bindings:[binding('observedValue'),{...binding('threshold'),type:'LITERAL',value:80}],actions:[action()],windowSeconds:null as number|null})
const form=ref<any>(empty()),names=computed(()=>form.value.bindings.map((item:any)=>item.name).filter(Boolean)),expression=computed(()=>{const f=form.value;if(f.template==='EXISTING')return f.existingExpression;if(f.template==='COMPARE')return f.left&&f.right?f.left+' '+f.operator+' '+f.right:'';if(f.template==='BOOLEAN')return f.left?f.left+' == '+String(f.expected):'';return f.left&&f.min&&f.max?f.left+' >= '+f.min+' && '+f.left+' <= '+f.max:''})
const numeric=(type:string)=>type==='INTEGER'||type==='DOUBLE',deviceSource=(type:string)=>['DEVICE_ATTRIBUTE','DEVICE_OPERATION_STATE','DEVICE_COMMAND_LIFECYCLE'].includes(type),nodeSource=(type:string)=>['NODE_LIFECYCLE_STATE','NODE_INTERNAL_VARIABLE'].includes(type),sourceLabel=(type:string)=>({DEVICE_ATTRIBUTE:'设备属性',DEVICE_OPERATION_STATE:'设备运行状态',DEVICE_COMMAND_LIFECYCLE:'设备命令生命周期',NODE_LIFECYCLE_STATE:'节点生命周期',NODE_INTERNAL_VARIABLE:'节点内部变量',TASK_LIFECYCLE_STATE:'任务生命周期'}[type]||type)
const parameterDefinitions=(item:any)=>{const capability=capabilitiesFor(item.deviceInstanceId).find((x:any)=>x.capabilityName===item.capabilityName);const raw=capability?.capabilityParameters;if(Array.isArray(raw))return raw.map((x:any)=>({name:x.parameterName||x.name,dataType:x.dataType||'STRING'}));if(raw&&typeof raw==='object')return Object.entries(raw).map(([name,value]:any)=>({name,dataType:value?.dataType||'STRING'}));return []};function initParameters(item:any){item.parameters={};parameterDefinitions(item).forEach((x:any)=>item.parameters[x.name]=x.dataType==='BOOLEAN'?false:'')};const instancesFor=(id:any)=>instances.value.filter((item:any)=>Number(item.deviceModelId||item.modelId)===Number(id)),attributesFor=(id:any)=>{const model=models.value.find((item:any)=>Number(item.id||item.modelId)===Number(id));return Array.isArray(model?.attributes)?model.attributes:[]},capabilitiesFor=(id:any)=>{const instance=instances.value.find((item:any)=>Number(item.id)===Number(id));const model=models.value.find((item:any)=>Number(item.id||item.modelId)===Number(instance?.deviceModelId||instance?.modelId));return Array.isArray(model?.capabilities)?model.capabilities:[]},nodesFor=(id:any)=>workflows.value.find((item:any)=>Number(item.id)===Number(id))?.nodesDef||[]
async function refs(){const [o,m,i,w,t]=await Promise.all([axios.get('/api/constraint/rule/options').catch(()=>null),axios.get('/api/device/model/list').catch(()=>null),axios.get('/api/device/instance/list').catch(()=>null),axios.get('/api/workflow/list').catch(()=>null),axios.get('/api/task/page',{params:{pageNo:1,pageSize:500}}).catch(()=>null)]);if(o?.data?.success){sourceTypes.value=o.data.data.observableSourceTypes||sourceTypes.value;dataTypes.value=(o.data.data.dataTypes||dataTypes.value).filter((x:string)=>x!=='JSON');systemActions.value=o.data.data.systemViolationActions||systemActions.value}if(m?.data?.success)models.value=m.data.data||[];if(i?.data?.success)instances.value=i.data.data||[];if(w?.data?.success)workflows.value=w.data.data||[];if(t?.data?.success)tasks.value=t.data.data?.records||[]}
async function load(){loading.value=true;try{const res=await axios.get('/api/constraint/rule/page',{params:query});if(!res.data?.success)throw Error(res.data?.message||'加载失败');items.value=res.data.data?.records||[];total.value=res.data.data?.total||0}catch(e:any){ElMessage.error(e.message||'加载约束规则失败')}finally{loading.value=false}}
function addBinding(){form.value.bindings.push(binding('variable'+(form.value.bindings.length+1)))}function addAction(){form.value.actions.push(action())}
function bindings(){const result:any={};for(const item of form.value.bindings){if(!item.name)throw Error('变量名不能为空');if(result[item.name])throw Error('变量名不能重复');if(item.type==='LITERAL'){if(item.value===null||item.value===undefined||item.value==='')throw Error('固定变量缺少值');result[item.name]={bindingType:'LITERAL',value:item.value};continue}const source:any={sourceType:item.sourceType,dataType:item.dataType};if(deviceSource(item.sourceType)){if(!item.deviceModelId)throw Error('设备变量必须选择设备模型');source.deviceModelId=item.deviceModelId;if(item.deviceInstanceId)source.deviceInstanceId=item.deviceInstanceId;if(item.sourceType==='DEVICE_ATTRIBUTE'){if(!item.targetName)throw Error('设备属性不能为空');source.targetName=item.targetName}if(item.sourceType==='DEVICE_OPERATION_STATE')source.regionName=item.regionName}else if(nodeSource(item.sourceType)){if(!item.workflowTemplateId||!item.nodeName)throw Error('节点变量必须选择工作流和节点');source.workflowTemplateId=item.workflowTemplateId;source.nodeName=item.nodeName;if(item.sourceType==='NODE_INTERNAL_VARIABLE'){if(!item.variableName)throw Error('内部变量不能为空');source.variableName=item.variableName}}else{if(!item.taskId)throw Error('任务生命周期变量必须选择任务');source.taskId=item.taskId}result[item.name]={bindingType:'OBSERVABLE',source}}return result}
function actions(){if(!form.value.actions.length)throw Error('请至少添加一个违规动作');return form.value.actions.map((item:any)=>{if(item.type==='SYSTEM'){if(item.action!=='ALERT'&&!item.taskId)throw Error(item.action+'必须选择目标任务');return{actionType:'SYSTEM',action:item.action,targetTaskId:item.action==='ALERT'?null:item.taskId}}if(!item.deviceInstanceId||!item.capabilityName)throw Error('设备能力动作必须选择设备和能力');return{actionType:'DEVICE_CAPABILITY',deviceInstanceId:item.deviceInstanceId,capabilityName:item.capabilityName,parameters:item.parameters}})}
function edit(row:any){const next=empty();Object.assign(next,{id:row.id,ruleName:row.ruleName||'',description:row.description||'',isEnabled:row.isEnabled!==false,template:'EXISTING',existingExpression:row.expression||'',windowSeconds:row.windowSeconds??null});next.bindings=Object.entries(row.bindings||{}).map(([name,v]:any)=>{const s=v.source||{};return{...binding(name),name,type:v.bindingType,sourceType:s.sourceType||'DEVICE_ATTRIBUTE',dataType:s.dataType||'DOUBLE',deviceModelId:s.deviceModelId||null,deviceInstanceId:s.deviceInstanceId||null,targetName:s.targetName||'',regionName:s.regionName||'CMD',workflowTemplateId:s.workflowTemplateId||null,nodeName:s.nodeName||'',variableName:s.variableName||'',taskId:s.taskId||null,value:v.value}});next.actions=(row.violationActions||[]).map((v:any)=>({...action(),type:v.actionType==='DEVICE_CAPABILITY'?'DEVICE_CAPABILITY':'SYSTEM',action:v.action||'ALERT',taskId:v.targetTaskId||null,deviceInstanceId:v.deviceInstanceId||null,capabilityName:v.capabilityName||'',parameters:v.parameters||{}}));return next}
async function open(row?:any){mode.value=row?'edit':'create';form.value=row?edit(row):empty();visible.value=true;await refs()}async function save(){if(!await formRef.value?.validate().catch(()=>false))return;if(!expression.value)return ElMessage.error('请完成表达式模板配置');try{const payload={id:form.value.id,ruleName:form.value.ruleName.trim(),description:form.value.description.trim(),expression:expression.value,bindings:bindings(),windowSeconds:form.value.windowSeconds,violationActions:actions(),isEnabled:form.value.isEnabled};saving.value=true;const res=payload.id?await axios.put('/api/constraint/rule/'+payload.id,payload):await axios.post('/api/constraint/rule',payload);if(!res.data?.success)throw Error(res.data?.message||'保存失败');ElMessage.success('约束规则已保存');visible.value=false;load()}catch(e:any){ElMessage.error(e.message||'保存约束规则失败')}finally{saving.value=false}}
async function setEnabled(row:any,value:boolean){try{const res=await axios.patch('/api/constraint/rule/'+row.id+'/enabled',null,{params:{enabled:value}});if(!res.data?.success)throw Error(res.data?.message||'更新失败')}catch(e:any){row.isEnabled=!value;ElMessage.error(e.message||'更新失败')}}async function remove(row:any){try{const res=await axios.delete('/api/constraint/rule/'+row.id);if(!res.data?.success)throw Error(res.data?.message||'删除失败');ElMessage.success('约束规则已删除');load()}catch(e:any){ElMessage.error(e.message||'删除失败')}}onMounted(()=>{load();refs()})
